def minEditsToMatchPattern(s, p):
    n = len(p)
    prev = [0] * (n + 1)
    for j in range(1, n + 1):
        prev[j] = prev[j - 1] + (0 if p[j - 1] == '*' else 1)
    for i in range(1, len(s) + 1):
        a = s[i - 1]
        cur = [i] + [0] * n
        for j in range(1, n + 1):
            c = p[j - 1]
            if c == '*':
                x = prev[j]
                y = cur[j - 1]
                cur[j] = x if x < y else y
            else:
                x = prev[j - 1] + (0 if (c == '?' or c == a) else 1)
                y = prev[j] + 1
                if y < x:
                    x = y
                y = cur[j - 1] + 1
                if y < x:
                    x = y
                cur[j] = x
        prev = cur
    return prev[n]
